import java.util.*;
import java.io.*;

public class Main {
    static final int MOD = 1000000007;

    static class Modular {
        int value;

        Modular(long v) {
            v %= MOD;
            if (v < 0) v += MOD;
            this.value = (int) v;
        }

        static int inverse(int a, int m) {
            int g = m, r = a, x = 0, y = 1;
            while (r != 0) {
                int q = g / r;
                int tmp = g % r;
                g = r;
                r = tmp;
                int x1 = x - q * y;
                x = y;
                y = x1;
            }
            return x < 0 ? x + m : x;
        }

        Modular add(Modular other) {
            int res = this.value + other.value;
            if (res >= MOD) res -= MOD;
            return new Modular(res);
        }

        Modular subtract(Modular other) {
            int res = this.value - other.value;
            if (res < 0) res += MOD;
            return new Modular(res);
        }

        Modular multiply(Modular other) {
            long res = (long) this.value * other.value;
            res %= MOD;
            return new Modular(res);
        }

        Modular divide(Modular other) {
            return this.multiply(new Modular(inverse(other.value, MOD)));
        }

        Modular pow(long p) {
            Modular result = new Modular(1);
            Modular base = new Modular(this.value);
            while (p > 0) {
                if ((p & 1) == 1) {
                    result = result.multiply(base);
                }
                base = base.multiply(base);
                p >>= 1;
            }
            return result;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine().trim());
        Modular[][] probability = new Modular[N][N];

        for (int i = 0; i < N; i++) {
            String[] parts = br.readLine().trim().split("\\s+");
            for (int j = 0; j < N; j++) {
                int p = Integer.parseInt(parts[j]);
                probability[i][j] = new Modular(p).divide(new Modular(100));
            }
        }

        Map<List<Boolean>, Modular> possibleStates = new HashMap<>();
        List<Boolean> initial = new ArrayList<>(Collections.nCopies(1 << N, false));
        initial.set(0, true);
        possibleStates.put(initial, new Modular(1));

        for (int left = 0; left < N; left++) {
            Map<List<Boolean>, Modular> newStates = new HashMap<>();
            for (int currentMask = 0; currentMask < (1 << N); currentMask++) {
                Modular prod = new Modular(1);
                for (int right = 0; right < N; right++) {
                    if (((currentMask >> right) & 1) != 0) {
                        prod = prod.multiply(probability[left][right]);
                    } else {
                        prod = prod.multiply(new Modular(1).subtract(probability[left][right]));
                    }
                }
                for (Map.Entry<List<Boolean>, Modular> entry : possibleStates.entrySet()) {
                    List<Boolean> possibleMask = entry.getKey();
                    Modular prob = entry.getValue();
                    List<Boolean> tempState = new ArrayList<>(Collections.nCopies(1 << N, false));
                    for (int mask = 0; mask < (1 << N); mask++) {
                        if (possibleMask.get(mask)) {
                            for (int i = 0; i < N; i++) {
                                if (((currentMask >> i) & 1) != 0 && ((mask >> i) & 1) == 0) {
                                    tempState.set(mask | (1 << i), true);
                                }
                            }
                        }
                    }
                    newStates.put(tempState, newStates.getOrDefault(tempState, new Modular(0)).add(prob.multiply(prod)));
                }
            }
            possibleStates = newStates;
        }

        Modular answer = new Modular(0);
        int fullMask = (1 << N) - 1;
        for (Map.Entry<List<Boolean>, Modular> p : possibleStates.entrySet()) {
            if (p.getKey().get(fullMask)) {
                answer = answer.add(p.getValue());
            }
        }

        System.out.println(answer.value);
    }
}
